327	        if (this.email != null && !this.email.isBlank()) {
328	            points += 2;
329	        }
330	        if (this.namesakeCount != null && this.namesakeCount == 0) {
331	            points += 1;
332	        }
333	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
334	            points += 2;
335	        }
336	        if (this.registrationDate != null
337	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
338	            points += 3;
339	        }
