434	            countryCode = "61";
435	        } else if (digits.startsWith("1")) {
436	            countryCode = "1";
437	        } else {
438	            countryCode = digits.length() > 2 ? digits.substring(0, 2) : digits;
439	        }
440	        String national = digits.substring(countryCode.length());
441	        StringBuilder display = new StringBuilder("+").append(countryCode);
