463	    /**
464	     * Computes the consolidated {@code identityKey} for the given identity-bearing fields: the
465	     * lower-case hex SHA-256 digest of
466	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The {@code email}
467	     * is lower-cased (empty when absent) and the {@code lastName} is reduced to its Soundex code
468	     * (see {@link #soundex}). The {@code telephone} is expected already normalized to E.164 form.
469	     *
470	     * @param telephone the owner's normalized (E.164) telephone, possibly {@code null}
471	     * @param email     the owner's email, possibly {@code null}
472	     * @param lastName  the owner's last name, possibly {@code null}
473	     * @return the lower-case hex SHA-256 identity key
474	     */
475	    public static String identityKey(String telephone, String email, String lastName) {
476	        String telephonePart = telephone == null ? "" : telephone;
477	        String emailPart = email == null ? "" : email.toLowerCase(Locale.ROOT);
478	        return sha256Hex(telephonePart + "|" + emailPart + "|" + soundex(lastName));
479	    }
480	
481	    /**
482	     * Returns the American Soundex code of {@code value}: the first letter followed by three
483	     * digits encoding the remaining consonants (b,f,p,v→1; c,g,j,k,q,s,x,z→2; d,t→3; l→4; m,n→5;
484	     * r→6), where vowels and {@code h}/{@code w} are not coded, adjacent letters with the same
485	     * code collapse to one (and a code repeated across an {@code h}/{@code w} is treated as
486	     * adjacent), and the result is right-padded with zeros to length four. A {@code null} or
487	     * letter-free value yields the empty string.
488	     *
489	     * @param value the value to encode, possibly {@code null}
490	     * @return the four-character Soundex code, or the empty string when there is no letter
491	     */
492	    public static String soundex(String value) {
493	        if (value == null) {
494	            return "";
495	        }
496	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
497	        if (letters.isEmpty()) {
498	            return "";
499	        }
500	        StringBuilder code = new StringBuilder();
501	        code.append(letters.charAt(0));
502	        char previous = soundexDigit(letters.charAt(0));
503	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
504	            char c = letters.charAt(i);
505	            if (c == 'H' || c == 'W') {
506	                continue;
507	            }
508	            char digit = soundexDigit(c);
509	            if (digit != '0' && digit != previous) {
510	                code.append(digit);
511	            }
512	            previous = (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y')
513	                ? '0' : digit;
514	        }
515	        while (code.length() < 4) {
516	            code.append('0');
517	        }
518	        return code.toString();
519	    }
520	
521	    private static char soundexDigit(char c) {
522	        switch (c) {
523	            case 'B': case 'F': case 'P': case 'V':
524	                return '1';
525	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
526	                return '2';
527	            case 'D': case 'T':
528	                return '3';
529	            case 'L':
530	                return '4';
531	            case 'M': case 'N':
532	                return '5';
533	            case 'R':
534	                return '6';
535	            default:
536	                return '0';
537	        }
538	    }
539	
540	    private static String sha256Hex(String value) {
541	        try {
542	            byte[] digest = MessageDigest.getInstance("SHA-256")
543	                .digest(value.getBytes(StandardCharsets.UTF_8));
544	            StringBuilder sb = new StringBuilder(digest.length * 2);
545	            for (byte b : digest) {
546	                sb.append(String.format("%02x", b));
547	            }
548	            return sb.toString();
549	        }
550	        catch (NoSuchAlgorithmException e) {
551	            throw new IllegalStateException("SHA-256 not available", e);
552	        }
553	    }
