200	    /**
201	     * Emits the immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger, in
202	     * addition to the human-readable audit line. The event is a JSON object
203	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}} where {@code seq}
204	     * is a monotonically increasing integer across every create (see {@link #EVENT_SEQ}).
205	     *
206	     * <p>The event carries the owner's <em>current</em> primary identifier under
207	     * {@code memberId}; see {@link #primaryIdentifier(Owner)} — the single place that decides which
208	     * field is the primary identifier.
209	     *
210	     * @param owner the just-created, already-persisted owner
211	     */
212	    private static void emitOwnerCreatedEvent(Owner owner) {
213	        long seq = EVENT_SEQ.incrementAndGet();
214	        String event = "{"
215	            + "\"seq\":" + seq
216	            + ",\"ownerId\":" + owner.getId()
217	            + ",\"memberId\":" + jsonString(primaryIdentifier(owner))
218	            + ",\"membershipLevel\":" + owner.getMembershipLevel()
219	            + ",\"event\":\"OWNER_CREATED\""
220	            + "}";
221	        AUDIT.info(event);
222	    }
