235	    /**
236	     * Renders {@code value} as a JSON string literal (quoted and escaped), or the JSON {@code null}
237	     * literal when {@code value} is {@code null}.
238	     *
239	     * @param value the string to render, possibly {@code null}
240	     * @return a JSON string literal, or {@code null}
241	     */
242	    private static String jsonString(String value) {
243	        if (value == null) {
244	            return "null";
245	        }
246	        StringBuilder sb = new StringBuilder(value.length() + 2);
247	        sb.append('"');
248	        for (int i = 0; i < value.length(); i++) {
249	            char c = value.charAt(i);
250	            switch (c) {
251	                case '"' -> sb.append("\\\"");
252	                case '\\' -> sb.append("\\\\");
253	                case '\n' -> sb.append("\\n");
254	                case '\r' -> sb.append("\\r");
255	                case '\t' -> sb.append("\\t");
256	                default -> {
257	                    if (c < 0x20) {
258	                        sb.append(String.format("\\u%04x", (int) c));
259	                    }
260	                    else {
261	                        sb.append(c);
262	                    }
263	                }
264	            }
265	        }
266	        sb.append('"');
267	        return sb.toString();
268	    }
