352	    /**
353	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
354	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
355	     * Validation already rejects {@code null} values and the pattern-constrained fields
356	     * when blank, but {@code address} and {@code city} have no pattern, so a
357	     * whitespace-only value would otherwise slip through.
358	     *
359	     * @param ownerFieldsDto the submitted owner fields
360	     * @throws RequiredFieldsMissingException if any required field is missing or blank
361	     */
362	    /**
363	     * Common street-type abbreviations expanded during address normalization. Keys are the
364	     * upper-cased abbreviation tokens; values are their canonical expansions.
365	     */
366	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
367	        "ST", "STREET",
368	        "RD", "ROAD",
369	        "AVE", "AVENUE");
370	
371	    /**
372	     * Normalizes the submitted address on create, accepting either the structured form
373	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
374	     * form retained for backward compatibility. Each supplied field is canonicalized the same way
375	     * (trimmed, internal whitespace collapsed to a single space, upper-cased, and common
376	     * street-type abbreviations expanded — see {@link #ADDRESS_ABBREVIATIONS}), and the normalized
377	     * values are written back onto the request.
378	     *
379	     * <p>The structured fields are preferred when present: when a non-blank {@code addressLine1} is
380	     * supplied, the flat {@code address} is set to the composed value — the normalized
381	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended
382	     * when an {@code addressLine2} is present — otherwise it keeps the normalized flat value. The
383	     * composed {@code address} is therefore persisted, echoed back, and used by everything that
384	     * reads the flat address. A blank/absent value in every form leaves {@code address} blank so the
385	     * required-field check can report it as missing.
386	     *
387	     * @param ownerFieldsDto the submitted owner fields
388	     */
389	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
390	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
391	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
392	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
393	        ownerFieldsDto.setAddressLine1(addressLine1);
394	        ownerFieldsDto.setAddressLine2(addressLine2);
395	        String composed;
396	        if (addressLine1 != null && !addressLine1.isBlank()) {
397	            composed = (addressLine2 != null && !addressLine2.isBlank())
398	                ? addressLine1 + " " + addressLine2
399	                : addressLine1;
400	        }
401	        else {
402	            composed = flat;
403	        }
404	        ownerFieldsDto.setAddress(composed);
405	    }
406	
407	    /**
408	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
409	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
410	     * expanded to its full form. A {@code null} value is returned unchanged.
411	     *
412	     * @param raw the address to canonicalize, possibly {@code null}
413	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
414	     */
415	    private static String normalizeAddress(String raw) {
416	        if (raw == null) {
417	            return null;
418	        }
419	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
420	        if (collapsed.isEmpty()) {
421	            return collapsed;
422	        }
423	        String[] tokens = collapsed.split(" ");
424	        StringBuilder sb = new StringBuilder(collapsed.length());
425	        for (int i = 0; i < tokens.length; i++) {
426	            if (i > 0) {
427	                sb.append(' ');
428	            }
429	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
430	        }
431	        return sb.toString();
432	    }
