452	    /**
453	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
454	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
455	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
456	     */
457	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
458	        "NSW", new int[] {2000, 2099},
459	        "VIC", new int[] {3000, 3099},
460	        "QLD", new int[] {4000, 4099});
461	
462	    /**
463	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
464	     * {@code null} value is accepted. When present it has already been constrained to four digits
465	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
466	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
467	     * the postcode must fall within that region's inclusive range
468	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
469	     *
470	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
471	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
472	     *                                  city's region
473	     */
474	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
475	        String postcode = ownerFieldsDto.getPostcode();
476	        if (postcode == null) {
477	            return;
478	        }
479	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
480	            .regionFor(ownerFieldsDto.getCity());
481	        int[] range = REGION_POSTCODE_RANGE.get(region);
482	        if (range == null) {
483	            return;
484	        }
485	        int value = Integer.parseInt(postcode);
486	        if (value < range[0] || value > range[1]) {
487	            throw new InvalidPostcodeException(postcode);
488	        }
489	    }
