508	    /**
509	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
510	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
511	     * and country code are present they are kept; otherwise country code {@code '+61'} is
512	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
513	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
514	     * the national-number length must match the country: {@code '+61'} (Australia) requires
515	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
516	     *
517	     * @param raw the submitted telephone, possibly {@code null}
518	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
519	     */
520	    private static String toE164(String raw) {
521	        if (raw == null) {
522	            return null;
523	        }
524	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
525	        String digits;
526	        if (cleaned.startsWith("+")) {
527	            digits = cleaned.substring(1);
528	        } else {
529	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
530	            digits = "61" + national;
531	        }
532	        if (!digits.matches("[0-9]{8,15}")) {
533	            return null;
534	        }
535	        if (digits.startsWith("61")) {
536	            // Australia: exactly 9 national digits after the '+61' country code.
537	            if (digits.length() - 2 != 9) {
538	                return null;
539	            }
540	        } else if (digits.startsWith("1")) {
541	            // NANP: exactly 10 national digits after the '+1' country code.
542	            if (digits.length() - 1 != 10) {
543	                return null;
544	            }
545	        }
546	        return "+" + digits;
547	    }
