559	    /**
560	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
561	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
562	     * the parts may contain whitespace or a second {@code @}.
563	     */
564	    private static final Pattern EMAIL_PATTERN =
565	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
566	
567	    /**
568	     * Disposable email domains that are not accepted for an owner's email. A create whose email
569	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
570	     * rejected. Kept lower-cased to match the normalized email.
571	     */
572	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
573	        "mailinator.com",
574	        "tempmail.com",
575	        "guerrillamail.com");
576	
577	    /**
578	     * Normalizes the submitted email when present: the value is trimmed, required to be a
579	     * syntactically valid address, required not to use a disposable-email domain, and written back
580	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
581	     * left untouched — the field is optional.
582	     *
583	     * @param ownerFieldsDto the submitted owner fields
584	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
585	     *                               valid, or its domain is on the disposable-domain blocklist
586	     */
587	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
588	        String email = ownerFieldsDto.getEmail();
589	        if (email == null) {
590	            return;
591	        }
592	        String trimmed = email.strip();
593	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
594	            throw new InvalidEmailException(email);
595	        }
596	        String normalized = trimmed.toLowerCase(Locale.ROOT);
597	        String domain = normalized.substring(normalized.indexOf('@') + 1);
598	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
599	            throw new InvalidEmailException(email);
600	        }
601	        ownerFieldsDto.setEmail(normalized);
602	    }
