622	    /**
623	     * Establishes the effective registration date on create and rolls it onto a business day.
624	     * When the client does not supply a {@code registrationDate} it defaults to the server's
625	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
626	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
627	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
628	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
629	     * the memberId's fiscal-year segment and the daily create-limit).
630	     *
631	     * @param ownerFieldsDto the submitted owner fields
632	     */
633	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
634	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
635	        if (effective == null) {
636	            effective = LocalDate.now();
637	        }
638	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
639	    }
640	
641	    /**
642	     * Fixed public holidays that the business-day roll skips. A registration date that lands on
643	     * one of these dates is advanced to the next non-holiday business day (see
644	     * {@link #toBusinessDay}).
645	     */
646	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
647	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
648	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
649	        LocalDate.parse("2026-12-28"));
650	
651	    /**
652	     * Rolls a date forward to the next business day: any date that falls on a Saturday, a Sunday
653	     * or a listed public holiday is advanced one day at a time until it lands on a weekday that is
654	     * not a public holiday; any other date is returned unchanged.
655	     *
656	     * @param date the date to adjust
657	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday
658	     *         business day
659	     */
660	    private static LocalDate toBusinessDay(LocalDate date) {
661	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
662	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
663	            || PUBLIC_HOLIDAYS.contains(date)) {
664	            date = date.plusDays(1);
665	        }
666	        return date;
667	    }
668	
669	    /**
670	     * Assigns the owner's unified {@code memberId} on create, formatted
671	     * {@code '<REGION><FY><HASH8><CHK>'}: REGION is the region derived from the owner's postcode
672	     * (preferring the postcode range, falling back to the city — the same derivation that yields
673	     * the owner's {@code locality}, see
674	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)});
675	     * FY is the two-digit fiscal year of the owner's (business-day-adjusted) {@code registrationDate}
676	     * on a fiscal year that starts on 1 July, zero-padded (matching the owner's {@code fiscalYear});
677	     * HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
678	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} (the same
679	     * hash used by the region-and-hash identity); and CHK is a single Luhn check digit computed over
680	     * the digits of {@code <REGION><FY><HASH8>} — e.g. {@code 'NSW27A1B2C3D45'}. Because REGION and
681	     * HASH8 both derive from the identity fields, two owners in the same region and fiscal year share
682	     * a member id only when their normalized telephone and last name both match.
683	     *
684	     * <p>When the computed member id collides with an existing owner's {@code memberId}, it is
685	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
686	     * it unique among the existing owners, so distinct owners always receive distinct ids. Both
687	     * {@link #assignMemberId} and {@link #defaultRegistrationDate} must run first, so the owner's
688	     * {@code registrationDate} is already set.
689	     *
690	     * @param owner the owner being created (with its {@code postcode}, {@code city},
691	     *              {@code telephone}, {@code lastName} and {@code registrationDate} already set)
692	     */
693	    private void assignMemberId(Owner owner) {
694	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
695	            .regionFor(owner.getPostcode(), owner.getCity());
696	        String fy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
697	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
698	            .substring(0, 8).toUpperCase(Locale.ROOT);
699	        String core = region + fy + hash8;
700	        String base = core + luhnCheckDigit(core);
701	        Set<String> existing = this.clinicService.findAllOwners().stream()
702	            .map(Owner::getMemberId)
703	            .filter(Objects::nonNull)
704	            .collect(Collectors.toSet());
705	        String memberId = base;
706	        for (int n = 2; existing.contains(memberId); n++) {
707	            memberId = base + "-" + n;
708	        }
709	        owner.setMemberId(memberId);
710	    }
711	
712	    /**
713	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value},
714	     * ignoring any non-digit characters.
715	     *
716	     * @param value the value whose digits the check digit is computed over
717	     * @return the Luhn check digit, 0 to 9
718	     */
719	    private static int luhnCheckDigit(String value) {
720	        int sum = 0;
721	        boolean dbl = true;
722	        for (int i = value.length() - 1; i >= 0; i--) {
723	            char c = value.charAt(i);
724	            if (c < '0' || c > '9') {
725	                continue;
726	            }
727	            int d = c - '0';
728	            if (dbl) {
729	                d *= 2;
730	                if (d > 9) {
731	                    d -= 9;
732	                }
733	            }
734	            sum += d;
735	            dbl = !dbl;
736	        }
737	        return (10 - (sum % 10)) % 10;
738	    }
739	
740	    /**
741	     * Assigns the owner's {@code householdId} on create: a stable, deterministic identifier for
742	     * the household, the first 12 hex characters of the SHA-256 digest of the owner's normalized
743	     * {@code lastName} and {@code postcode} (see {@link #householdIdFor}). Because it is derived
744	     * purely from those two fields, every owner sharing a last name and postcode is assigned the
745	     * same value automatically — including one joining an existing household via
746	     * {@code sharesHousehold} — independent of create order.
747	     *
748	     * @param owner the owner being created (with its {@code lastName} and {@code postcode} already set)
749	     */
750	    private void assignHouseholdId(Owner owner) {
751	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
752	    }
753	
754	    /**
755	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
756	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
757	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
758	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
759	     * every owner sharing a last name and postcode receives the same value, independent of create
760	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #assignHouseholdMemberCount}
761	     * and {@link #assignMembershipLevelCap} (which read the household membership).
762	     *
763	     * @param lastName the owner's last name
764	     * @param postcode the owner's postcode, possibly {@code null}
765	     * @return the derived household id
766	     */
767	    private static String householdIdFor(String lastName, String postcode) {
768	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
769	        return sha256Hex(key).substring(0, 12);
770	    }
771	
772	    /**
773	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
774	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
775	     * after this create. Because {@code householdId} is derived from the owner's {@code lastName}
776	     * and {@code postcode} (see {@link #assignHouseholdId}), the count reflects every
777	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
778	     * The count is taken before this owner is persisted, so it is one more than the number of
779	     * existing household members.
780	     *
781	     * @param owner the owner being created (with its {@code householdId} already assigned)
782	     */
783	    private void assignHouseholdMemberCount(Owner owner) {
784	        String householdId = owner.getHouseholdId();
785	        long existing = this.clinicService.findAllOwners().stream()
786	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
787	            .count();
788	        owner.setHouseholdMemberCount((int) (existing + 1));
789	    }
790	
791	    /**
792	     * Assigns the owner's {@code membershipLevelCap} on create, which bounds the level returned by
793	     * {@link org.springframework.samples.petclinic.model.Owner#getMembershipLevel()}. A new owner
794	     * joining an existing household without declaring it (i.e. admitted via its {@code email}, not
795	     * via {@code sharesHousehold}) may not hold a membership level more than one above the current
796	     * maximum membership level among the existing members of its household: the cap is that maximum
797	     * plus one. When the household has no existing member no cap applies, and a declared member
798	     * (one that opted in via {@code sharesHousehold}) is never capped; in both cases the cap is left
799	     * unset so the points-derived level stands. The scan is taken over the existing owners before
800	     * this one is persisted, so it reflects only pre-existing household members.
801	     *
802	     * @param owner the owner being created (with its {@code householdId} already assigned)
803	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
804	     */
805	    private void assignMembershipLevelCap(Owner owner, boolean declaredHouseholdMember) {
806	        if (declaredHouseholdMember) {
807	            owner.setMembershipLevelCap(null);
808	            return;
809	        }
810	        String householdId = owner.getHouseholdId();
811	        Integer maxLevel = this.clinicService.findAllOwners().stream()
812	            .filter(other -> !other.isDeleted())
813	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
814	            .map(Owner::getMembershipLevel)
815	            .filter(Objects::nonNull)
816	            .max(Integer::compareTo)
817	            .orElse(null);
818	        owner.setMembershipLevelCap(maxLevel == null ? null : maxLevel + 1);
819	    }
820	
821	    /**
822	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
823	     * already share this owner's {@code firstName} and {@code lastName}, compared
824	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
825	     * pre-existing namesakes.
826	     *
827	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
828	     */
829	    private void assignNamesakeCount(Owner owner) {
830	        String firstName = owner.getFirstName();
831	        String lastName = owner.getLastName();
832	        long count = this.clinicService.findAllOwners().stream()
833	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
834	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
835	            .count();
836	        owner.setNamesakeCount((int) count);
837	    }
838	
839	    /**
840	     * The number of owners that must already carry a registration date before a subsequent
841	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
842	     * once the count of owners already registered on that day <em>exceeds</em> this value.
843	     */
844	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
845	
846	    /**
847	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
848	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
849	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
850	     * existing owners before this one is persisted, so it reflects only the owners already
851	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
852	     *
853	     * @param owner the owner being created (with its {@code registrationDate} already set)
854	     */
855	    private void assignBulkSignupWarning(Owner owner) {
856	        LocalDate registrationDate = owner.getRegistrationDate();
857	        long count = this.clinicService.findAllOwners().stream()
858	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
859	            .count();
860	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
861	    }
862	
863	    /**
864	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
865	     * {@link #rejectDuplicateIdentity}, so this owner is not a hard duplicate. A declared household
866	     * member (one that opted in via {@code sharesHousehold}) is never flagged: it is an
867	     * acknowledged member of the household, not a suspected duplicate, so {@code possibleDuplicate}
868	     * is {@code false}. Otherwise it is a <em>possible</em> duplicate when an existing owner shares
869	     * its {@code soundex(lastName)} (see {@link Owner#soundex}) and its {@code postcode} but has a
870	     * <em>different</em> {@code identityKey} (so it was not already rejected as a hard duplicate —
871	     * typically a different telephone or email): {@code possibleDuplicate} is set {@code true} and
872	     * {@code possibleDuplicateOf} to that owner's id (the earliest such owner by id when several
873	     * match). Otherwise {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf}
874	     * is left unset. The scan is taken over the existing owners before this one is persisted.
875	     *
876	     * @param owner the owner being created (with its {@code lastName}, {@code postcode},
877	     *              already-normalized {@code telephone} and {@code email} set)
878	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
879	     */
880	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
881	        if (declaredHouseholdMember) {
882	            owner.setPossibleDuplicate(false);
883	            owner.setPossibleDuplicateOf(null);
884	            return;
885	        }
886	        String lastName = owner.getLastName();
887	        String postcode = owner.getPostcode();
888	        Integer matchId = null;
889	        if (lastName != null && postcode != null) {
890	            String soundex = Owner.soundex(lastName);
891	            String identityKey = owner.getIdentityKey();
892	            matchId = this.clinicService.findAllOwners().stream()
893	                .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName())))
894	                .filter(existing -> postcode.equals(existing.getPostcode()))
895	                .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
896	                .map(Owner::getId)
897	                .filter(id -> id != null)
898	                .min(Integer::compareTo)
899	                .orElse(null);
900	        }
901	        owner.setPossibleDuplicate(matchId != null);
902	        owner.setPossibleDuplicateOf(matchId);
903	    }
904	
905	    /**
906	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
907	     *
908	     * @param value the string to hash
909	     * @return the 64-character lower-case hex digest
910	     */
911	    private static String sha256Hex(String value) {
912	        try {
913	            byte[] digest = MessageDigest.getInstance("SHA-256")
914	                .digest(value.getBytes(StandardCharsets.UTF_8));
915	            StringBuilder sb = new StringBuilder(digest.length * 2);
916	            for (byte b : digest) {
917	                sb.append(String.format("%02x", b));
918	            }
919	            return sb.toString();
920	        }
921	        catch (NoSuchAlgorithmException e) {
922	            throw new IllegalStateException("SHA-256 not available", e);
923	        }
924	    }
925	
926	    /**
927	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
928	     * owner (owners flagged deleted are ignored). The key is the SHA-256 hex of
929	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
930	     * {@link Owner#identityKey}), and a create is a duplicate only when its <em>whole</em> key
931	     * matches an existing owner's. Because the telephone is part of the key, two owners sharing a
932	     * last name and postcode but with different telephones have different identity keys and are
933	     * both allowed (the second is flagged a soft match, see {@link #assignPossibleDuplicate}); only
934	     * an exact full-key match is rejected. The submitted telephone and email have already been
935	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}, and each existing
936	     * owner's key is computed the same way so differing input formats collapse to the same value.
937	     *
938	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
939	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
940	     *                                    whole identity key
941	     */
942	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
943	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
944	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
945	        boolean duplicate = this.clinicService.findAllOwners().stream()
946	            .filter(owner -> !owner.isDeleted())
947	            .map(Owner::getIdentityKey)
948	            .anyMatch(identityKey::equals);
949	        if (duplicate) {
950	            throw new DuplicateIdentityException(identityKey);
951	        }
952	    }
953	
954	    /**
955	     * The maximum number of owners permitted in a single city. A create is rejected once the
956	     * owner's city already contains this many owners.
957	     */
958	    private static final long CITY_CAPACITY = 50;
959	
960	    /**
961	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
962	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
963	     * before this owner is persisted.
964	     *
965	     * @param city the submitted city
966	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
967	     */
968	    private void rejectCityAtCapacity(String city) {
969	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
970	            throw new CityAtCapacityException(city);
971	        }
972	    }
973	
974	    /**
975	     * The number of owners in a city at which a create begins warning that the city is approaching
976	     * its {@link #CITY_CAPACITY} limit. A create is flagged with {@code capacityWarning} once the
977	     * city already holds this many owners (up to, but not including, the hard limit).
978	     */
979	    private static final long CAPACITY_WARNING_THRESHOLD = 40;
980	
981	    /**
982	     * Assigns the owner's {@code capacityWarning} on create: {@code true} when the owner's city
983	     * already holds between {@link #CAPACITY_WARNING_THRESHOLD} and {@link #CITY_CAPACITY} minus one
984	     * owners (inclusive) — i.e. it is approaching, but has not reached, the hard capacity limit —
985	     * otherwise {@code false}. The count is taken over the existing owners before this one is
986	     * persisted, using the same case-insensitive city comparison as {@link #rejectCityAtCapacity}.
987	     * The hard rejection at {@link #CITY_CAPACITY} is enforced separately, so a warned create is
988	     * still allowed.
989	     *
990	     * @param owner the owner being created (with its {@code city} already set)
991	     */
992	    private void assignCapacityWarning(Owner owner) {
993	        long count = countOwnersInCity(owner.getCity());
994	        owner.setCapacityWarning(count >= CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY);
995	    }
996	
997	    /**
998	     * Counts the existing owners whose {@code city} equals the given city, compared
999	     * case-insensitively (matching {@link #assignCustomerCode}). The count is taken over the
1000	     * current owners, before any in-flight create is persisted.
1001	     *
1002	     * @param city the city to count owners for
1003	     * @return the number of existing owners in that city
1004	     */
1005	    private long countOwnersInCity(String city) {
1006	        return this.clinicService.findAllOwners().stream()
1007	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
1008	            .count();
1009	    }
1010	
1011	    /**
1012	     * The maximum number of owners permitted to be created in a single day. A create is
1013	     * rejected once this many owners already carry today's {@code registrationDate}.
1014	     */
1015	    private static final long DAILY_LIMIT = 100;
1016	
1017	    /**
1018	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
1019	     * business day as their {@code registrationDate}. The day counted against is this create's
1020	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
1021	     * so owners are counted per adjusted business day. The count is taken before this owner is
1022	     * persisted.
1023	     *
1024	     * @param businessDay the effective, business-day-adjusted registration date of this create
1025	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
1026	     */
1027	    private void rejectDailyLimit(LocalDate businessDay) {
1028	        long count = this.clinicService.findAllOwners().stream()
1029	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
1030	            .count();
1031	        if (count >= DAILY_LIMIT) {
1032	            throw new DailyOwnerLimitExceededException(businessDay);
1033	        }
1034	    }
1035	
1036	    /**
1037	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
1038	     * every internal run of whitespace is collapsed to a single space, and the result is
1039	     * lower-cased. A {@code null} value collapses to the empty string.
1040	     *
1041	     * @param value the value to canonicalize, possibly {@code null}
1042	     * @return the collapsed, lower-cased value
1043	     */
1044	    private static String collapse(String value) {
1045	        if (value == null) {
1046	            return "";
1047	        }
1048	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1049	    }
1050	
1051	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
1052	    @Override
1053	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
1054	        Owner owner = this.clinicService.findOwnerById(ownerId);
1055	        if (owner != null) {
1056	            Pet pet = owner.getPet(petId);
1057	            if (pet != null) {
1058	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
1059	            }
1060	        }
1061	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
1062	    }
1063	}
